import os
from fastapi import FastAPI, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, Field
from forge_core.store import Store
from forge_core.registry import ModelRegistry, TeamComposer, DEFAULT_ROLES
from forge_core.router import RouterService
from forge_core.domain import ModelProfile, WorkerSession, ForgeEvent, QuestStatus, DomainError
from forge_core.quest_service import QuestService

db_path = os.getenv("FORGE_DB_PATH","data/forge.sqlite3")
store = Store(db_path)
registry = ModelRegistry(store)
composer = TeamComposer(registry)
router = RouterService(store,composer)
quest_service = QuestService(store)

app = FastAPI(title="FORGE Core",version="0.2.0")
app.add_middleware(CORSMiddleware,
    allow_origins=["http://127.0.0.1:5173","http://localhost:5173","tauri://localhost"],
    allow_credentials=True,allow_methods=["GET","POST"],allow_headers=["Content-Type"])

class MessageIn(BaseModel):
    content: str = Field(min_length=1,max_length=20000)

class QuestTransitionIn(BaseModel):
    status: QuestStatus

@app.get("/health")
def health():
    state=store.ensure_router()
    return {"status":"ok","product":"FORGE","conversation_id":"main",
            "router_session_id":state["router_session_id"]}

@app.get("/api/conversation")
def get_conversation():
    return {"conversation_id":"main","router":store.ensure_router(),
            "messages":store.list_messages()}

@app.post("/api/conversation/message")
def send_message(payload: MessageIn):
    return router.handle_user_message(payload.content)

@app.get("/api/quests")
def list_quests():
    return store.list_quests()

@app.get("/api/quests/{quest_id}")
def get_quest(quest_id: str):
    quest=store.get_quest(quest_id)
    if quest is None:
        raise HTTPException(status_code=404,detail="Quest not found")
    return {"quest":quest,"workers":store.list_workers(quest_id)}

@app.post("/api/quests/{quest_id}/transition")
def transition_quest(quest_id: str, payload: QuestTransitionIn):
    try:
        return quest_service.transition(quest_id, payload.status)
    except KeyError:
        raise HTTPException(status_code=404, detail="Quest not found")
    except DomainError as exc:
        raise HTTPException(status_code=409, detail=str(exc))

@app.post("/api/quests/{quest_id}/workers")
def propose_worker(quest_id: str,role: str,model_id: str | None = None):
    if store.get_quest(quest_id) is None:
        raise HTTPException(status_code=404,detail="Quest not found")
    worker=WorkerSession(quest_id=quest_id,role=role,model_id=model_id)
    store.save_worker(worker)
    store.append_event(ForgeEvent(event_type="worker.proposed",quest_id=quest_id,
                                  worker_id=worker.id,payload={"role":role,"hidden":True}))
    return worker

@app.get("/api/models")
def list_models():
    return registry.list()

@app.post("/api/models")
def upsert_model(profile: ModelProfile):
    return registry.upsert(profile)

@app.get("/api/events")
def list_events(after: int = 0,limit: int = 200):
    if after < 0:
        raise HTTPException(status_code=422,detail="'after' must be >= 0")
    return store.list_events(after=after,limit=max(1,min(limit,500)))

@app.get("/api/team/preview")
def preview_team():
    return composer.compose(DEFAULT_ROLES)

from .domain import QuestStatus, DomainError, validate_quest_transition, ForgeEvent, now_iso

class QuestService:
    def __init__(self, store):
        self.store = store

    def transition(self, quest_id: str, target: QuestStatus):
        record = self.store.get_quest(quest_id)
        if record is None:
            raise KeyError(quest_id)
        current = QuestStatus(record["status"])
        validate_quest_transition(current, target)
        timestamp = now_iso()
        updated = self.store.transition_quest(quest_id, target.value, timestamp)
        if not updated:
            raise RuntimeError("Quest disappeared during transition")
        self.store.append_event(ForgeEvent(
            event_type="quest.status_changed",
            quest_id=quest_id,
            payload={"from": current.value, "to": target.value}
        ))
        return self.store.get_quest(quest_id)

from .domain import RoleTemplate

DEFAULT_ROLES = [
    RoleTemplate(id="research",name="Research",description="Research and synthesis",
                 required_capabilities={"research":75,"writing":55}),
    RoleTemplate(id="math",name="Math",description="Formal reasoning and quantitative analysis",
                 required_capabilities={"math":80,"reasoning":75}),
    RoleTemplate(id="coding",name="Coding",description="Implement and debug software",
                 required_capabilities={"coding":80,"tool_use":65}),
    RoleTemplate(id="design",name="Design",description="Visual and interaction design",
                 required_capabilities={"design":75,"vision":60}),
    RoleTemplate(id="review",name="Reviewer",description="Independent verification",
                 required_capabilities={"reasoning":75,"instruction_following":75}),
]

class ModelRegistry:
    def __init__(self, store):
        self.store = store

    def upsert(self, profile):
        self.store.save_model(profile)
        return profile

    def list(self):
        return self.store.list_models()

    def candidates(self, required):
        ranked = []
        for model in self.list():
            if not model.enabled:
                continue
            if not required:
                fit = 50.0
            else:
                # Unknown capability remains a neutral-low candidate, never fabricated.
                fit = sum(model.capabilities.get(k,0.0) * min(v,100.0)/100.0
                          for k,v in required.items()) / len(required)
            ranked.append((model,round(fit,2)))
        return sorted(ranked,key=lambda item:item[1],reverse=True)

class TeamComposer:
    """Explainable baseline. Research-grade complementarity optimization is a later milestone."""
    def __init__(self, registry):
        self.registry = registry

    def compose(self, roles):
        proposals = []
        for role in roles:
            candidates = self.registry.candidates(role.required_capabilities)
            proposals.append({
                "role_id":role.id,
                "role_name":role.name,
                "required_capabilities":role.required_capabilities,
                "model_candidates":[
                    {"model_id":model.id,"provider":model.provider,"fit_score":score}
                    for model,score in candidates[:3]
                ],
                "status":"proposed"
            })
        return proposals

from .domain import IntentType, Quest, ConversationMessage, ForgeEvent
from .registry import DEFAULT_ROLES

class RouterService:
    """Bootstrap Router policy. Replace with a model-backed Agent Loop in Phase 1."""
    def __init__(self, store, composer):
        self.store, self.composer = store, composer
        self.store.ensure_router()

    @staticmethod
    def classify(text):
        value = text.casefold()
        if any(token in value for token in ("进度","怎么样了","status","状态")):
            return IntentType.STATUS_QUERY
        if any(token in value for token in ("继续","接着","上次","之前那个")):
            return IntentType.CONTINUE_QUEST
        if any(token in value for token in ("帮我","请你","研究","开发","设计","分析","完成","制作")):
            return IntentType.CREATE_QUEST
        return IntentType.CHAT

    def handle_user_message(self, text):
        user_message = ConversationMessage(role="user",content=text)
        self.store.add_message(user_message)
        intent = self.classify(text)
        if intent == IntentType.CREATE_QUEST:
            quest = Quest(title=text[:48],goal=text)
            self.store.save_quest(quest)
            team = self.composer.compose(DEFAULT_ROLES)
            self.store.append_event(ForgeEvent(event_type="quest.proposed",quest_id=quest.id,
                                               payload={"team_proposal":team}))
            reply = (f"我已将目标登记为后台 Quest「{quest.title}」。当前只生成了团队提案；"
                     "真实模型规划和 Worker 执行尚未接入。正式执行前会展示计划并请求批准。")
        elif intent == IntentType.STATUS_QUERY:
            quests = self.store.list_quests()
            reply = "目前没有后台 Quest。" if not quests else "当前 Quest：\n" + "\n".join(
                f"- {item['title']} [{item['status']}]" for item in quests[:10])
        elif intent == IntentType.CONTINUE_QUEST:
            reply = ("我会在同一个对话中关联已有 Quest。当前 Starter 尚未实现语义级 Quest Resolver；"
                     "如果有多个可能目标，我不会擅自选择。")
        else:
            reply = "我一直在这里。你可以在这个对话中持续交流；复杂目标会成为后台 Quest，由我统一协调隐藏 Worker。"
        assistant_message = ConversationMessage(role="assistant",content=reply,
                                                metadata={"intent":intent.value})
        self.store.add_message(assistant_message)
        return {"intent":intent.value,"user_message":user_message,
                "assistant_message":assistant_message}

from dataclasses import dataclass
from typing import Protocol, Any

@dataclass
class ModelRequest:
    model_id: str
    messages: list[dict[str,Any]]
    tools: list[dict] | None = None
    max_output_tokens: int = 2048

@dataclass
class ModelResponse:
    text: str
    tool_calls: list[dict]
    usage: dict

class ProviderAdapter(Protocol):
    async def generate(self, request: ModelRequest) -> ModelResponse: ...

class UnconfiguredProvider:
    async def generate(self, request: ModelRequest) -> ModelResponse:
        raise RuntimeError("No provider configured. No model call was performed.")

class ToolDefinition:
    def __init__(self,name,description,input_schema,risk="R0"):
        self.name=name
        self.description=description
        self.input_schema=input_schema
        self.risk=risk

class ToolRegistry:
    def __init__(self):
        self._tools = {}

    def register(self, tool):
        if tool.name in self._tools:
            raise ValueError(f"Tool already registered: {tool.name}")
        self._tools[tool.name] = tool

    def get(self,name):
        return self._tools.get(name)

class AgentLoop:
    """Native Agent Loop skeleton. Tool execution is blocked until policy enforcement exists."""
    def __init__(self,provider,tools,max_steps=8):
        self.provider=provider
        self.tools=tools
        self.max_steps=max_steps

    async def run(self,model_id,messages):
        trace=[]
        for step in range(self.max_steps):
            response=await self.provider.generate(ModelRequest(model_id=model_id,messages=messages))
            trace.append({"step":step,"text":response.text,"tool_calls":response.tool_calls})
            if not response.tool_calls:
                return {"status":"completed","text":response.text,"trace":trace}
            return {"status":"policy_engine_required","trace":trace}
        return {"status":"max_steps_reached","trace":trace}
